const SpreadsheetPopup: React.FC<SpreadsheetPopupProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  scale = 1,
  accentColor = "#107C41",
}) => {
  // No text involved, so no font loader call

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Background handling
  const bgColor = transparentBackground ? "#00000000" : backgroundColor;

  // Animation constants
  const entryDuration = 25;
  const exitDuration = 20;
  const totalFrames = durationInSeconds * fps;
  const exitStartFrame = totalFrames - exitDuration;

  // Spring Entry - Scale and Slide
  const springValue = spring({
    frame,
    fps,
    config: {
      damping: 14,
      stiffness: 120,
      mass: 0.8,
    },
  });

  // Interpolate for smooth fade in/out
  const opacity = interpolate(
    frame,
    [0, 10, exitStartFrame, totalFrames],
    [0, 1, 1, 0],
    { extrapolateRight: "clamp" }
  );

  // Slight slide up on exit
  const exitTranslateY = interpolate(
    frame,
    [exitStartFrame, totalFrames],
    [0, -50],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Layout sizing calculations
  const sheetWidth = Math.min(width * 0.8, 900);
  const sheetHeight = sheetWidth * 0.66; // 3:2 aspect ratio roughly

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: sheetWidth,
          height: sheetHeight,
          position: "relative",
          opacity,
          transform: `scale(${springValue * scale}) translateY(${exitTranslateY}px)`,
          transformOrigin: "center center",
        }}
      >
        <SpreadsheetGraphic 
          accentColor={accentColor} 
          width={sheetWidth} 
          height={sheetHeight} 
        />
      </div>
    </AbsoluteFill>
  );
};

export default SpreadsheetPopup;